import pandas as pd
import numpy as np
import json
from datetime import datetime

# ============================================================
# LOAD AND PREPARE DATA
# ============================================================
df = pd.read_csv('/app/benchmark/data.csv')
df_price = df[df['price'].notna()].copy()
df_reviews = df[df['reviews_per_month'].notna()].copy()

# Derived columns
df['is_professional'] = df['calculated_host_listings_count'] >= 5
df['is_entire_home'] = df['room_type'] == 'Entire home/apt'
df['last_review_dt'] = pd.to_datetime(df['last_review'], errors='coerce')
scrape_date = pd.Timestamp('2026-03-29')
df['days_since_review'] = (scrape_date - df['last_review_dt']).dt.days

# City order by listing count
city_order = df['city'].value_counts().index.tolist()

# ============================================================
# COMPUTE ALL KPIs
# ============================================================

# --- Section 1: Market Overview ---
listings_per_city = df.groupby('city').size().reindex(city_order)

room_type_pct = df.groupby('city')['room_type'].value_counts(normalize=True).unstack(fill_value=0) * 100
room_type_count = df.groupby('city')['room_type'].value_counts().unstack(fill_value=0)

# --- Section 2: Pricing ---
price_median_city = df_price.groupby('city')['price'].median().sort_values(ascending=False)
price_mean_city = df_price.groupby('city')['price'].mean().sort_values(ascending=False)

price_by_room = df_price.groupby(['city', 'room_type'])['price'].median().unstack(fill_value=0)
price_by_room_mean = df_price.groupby(['city', 'room_type'])['price'].mean().unstack(fill_value=0)

price_dispersion = df_price.groupby('city')['price'].agg(
    q25=lambda x: x.quantile(0.25),
    median='median',
    q75=lambda x: x.quantile(0.75),
    std='std',
    mean='mean'
).reset_index()
price_dispersion['iqr'] = price_dispersion['q75'] - price_dispersion['q25']
price_dispersion['cv'] = (price_dispersion['std'] / price_dispersion['mean']).round(2)

# --- Section 3: Supply Structure ---
prof_share = (df.groupby('city')['is_professional'].mean() * 100).sort_values(ascending=False)
entire_home_share = (df.groupby('city')['is_entire_home'].mean() * 100).sort_values(ascending=False)

host_listing_stats = df.groupby('city')['calculated_host_listings_count'].agg(['mean', 'median', 'max']).round(1)

# --- Section 4: Guest Demand ---
avg_reviews_month = df_reviews.groupby('city')['reviews_per_month'].mean().sort_values(ascending=False).round(2)

review_stats_city = df.groupby('city').agg(
    avg_total_reviews=('number_of_reviews', 'mean'),
    avg_ltm_reviews=('number_of_reviews_ltm', 'mean'),
    pct_with_reviews=('number_of_reviews', lambda x: (x > 0).mean() * 100)
).round(1)

review_recency_12m = df[df['days_since_review'] <= 365].groupby('city').size() / df.groupby('city').size() * 100
review_recency_12m = review_recency_12m.round(1).sort_values(ascending=False)

reviews_by_room = df_reviews.groupby(['city', 'room_type'])['reviews_per_month'].mean().unstack(fill_value=0).round(2)

# --- Section 5: Availability ---
avail_stats = df.groupby('city')['availability_365'].agg(['mean', 'median']).round(1)
avail_stats.columns = ['mean_avail', 'median_avail']

zero_avail_pct = (df.groupby('city').apply(lambda x: (x['availability_365'] == 0).mean() * 100, include_groups=False)).round(1)
zero_avail_pct.name = 'pct_zero_avail'

min_nights_stats = df.groupby('city')['minimum_nights'].agg(
    mean_min='mean',
    median_min='median',
    pct_over_30=lambda x: (x > 30).mean() * 100
).round(1)

# ============================================================
# Price data coverage info
# ============================================================
price_coverage = {}
for city in sorted(df['city'].unique()):
    total = len(df[df['city'] == city])
    with_price = len(df_price[df_price['city'] == city])
    price_coverage[city] = {'total': total, 'with_price': with_price, 'pct': round(with_price/total*100, 1)}

# ============================================================
# CHART DATA for Chart.js
# ============================================================

# Chart 1: Listings per city (horizontal bar)
chart1_labels = city_order
chart1_data = [int(listings_per_city[c]) for c in city_order]

# Chart 2: Median price by city (bar)
chart2_cities = price_median_city.index.tolist()
chart2_labels = chart2_cities
chart2_data = [round(float(price_median_city[c]), 0) for c in chart2_cities]

# Chart 3: Median price by room type (grouped bar)
room_types_for_chart = ['Entire home/apt', 'Private room', 'Shared room', 'Hotel room']
chart3_cities = ['Amsterdam', 'Bangkok', 'Barcelona', 'London', 'Rome']  # Cities with price data
chart3_datasets = []
colors_room = {
    'Entire home/apt': ('rgba(52, 152, 219, 0.8)', 'rgba(52, 152, 219, 1)'),
    'Private room': ('rgba(46, 204, 113, 0.8)', 'rgba(46, 204, 113, 1)'),
    'Shared room': ('rgba(243, 156, 18, 0.8)', 'rgba(243, 156, 18, 1)'),
    'Hotel room': ('rgba(155, 89, 182, 0.8)', 'rgba(155, 89, 182, 1)')
}
for rt in room_types_for_chart:
    if rt in price_by_room.columns:
        vals = []
        for c in chart3_cities:
            v = price_by_room.loc[c, rt] if c in price_by_room.index and rt in price_by_room.columns else 0
            vals.append(round(float(v), 0))
        chart3_datasets.append({
            'label': rt,
            'data': vals,
            'backgroundColor': colors_room[rt][0],
            'borderColor': colors_room[rt][1],
            'borderWidth': 1
        })

# Chart 4: Professional host share (horizontal bar)
chart4_cities = prof_share.index.tolist()
chart4_data = [round(float(prof_share[c]), 1) for c in chart4_cities]

# Chart 5: Entire home share (horizontal bar)
chart5_cities = entire_home_share.index.tolist()
chart5_data = [round(float(entire_home_share[c]), 1) for c in chart5_cities]

# Chart 6: Avg reviews per month (bar)
chart6_cities = avg_reviews_month.index.tolist()
chart6_data = [round(float(avg_reviews_month[c]), 2) for c in chart6_cities]

# Chart 7: Mean availability (bar)
chart7_cities = avail_stats.sort_values('mean_avail', ascending=False).index.tolist()
chart7_data = [round(float(avail_stats.loc[c, 'mean_avail']), 1) for c in chart7_cities]

# Chart 8: Room type mix (stacked bar per city)
chart8_cities = city_order
chart8_datasets = []
for rt in ['Entire home/apt', 'Private room', 'Shared room', 'Hotel room']:
    vals = []
    for c in chart8_cities:
        v = room_type_pct.loc[c, rt] if c in room_type_pct.index and rt in room_type_pct.columns else 0
        vals.append(round(float(v), 1))
    chart8_datasets.append({
        'label': rt,
        'data': vals,
        'backgroundColor': colors_room[rt][0],
        'borderColor': colors_room[rt][1],
        'borderWidth': 1
    })

# Chart 9: Zero availability % (bar)
chart9_cities = zero_avail_pct.sort_values(ascending=False).index.tolist()
chart9_data = [round(float(zero_avail_pct[c]), 1) for c in chart9_cities]

# ============================================================
# BUILD TABLES
# ============================================================

# Table: Market Overview
table_overview_rows = []
for city in city_order:
    total = int(listings_per_city[city])
    eh = int(room_type_count.loc[city, 'Entire home/apt']) if 'Entire home/apt' in room_type_count.columns else 0
    pr = int(room_type_count.loc[city, 'Private room']) if 'Private room' in room_type_count.columns else 0
    sr = int(room_type_count.loc[city, 'Shared room']) if 'Shared room' in room_type_count.columns else 0
    hr = int(room_type_count.loc[city, 'Hotel room']) if 'Hotel room' in room_type_count.columns else 0
    eh_pct = round(eh/total*100, 1)
    pr_pct = round(pr/total*100, 1)
    pc = price_coverage.get(city, {})
    price_note = f"{pc.get('with_price', 0)} ({pc.get('pct', 0)}%)" if pc else "N/A"
    table_overview_rows.append([city, f"{total:,}", f"{eh:,} ({eh_pct}%)", f"{pr:,} ({pr_pct}%)", f"{sr:,}", f"{hr:,}", price_note])

# Table: Price by city
table_price_rows = []
for _, row in price_dispersion.sort_values('median', ascending=False).iterrows():
    table_price_rows.append([
        row['city'],
        f"${row['median']:,.0f}",
        f"${row['mean']:,.0f}",
        f"${row['q25']:,.0f}",
        f"${row['q75']:,.0f}",
        f"${row['iqr']:,.0f}",
        f"{row['cv']:.2f}"
    ])

# Table: Professional host & entire home share
table_supply_rows = []
all_cities_sorted = sorted(df['city'].unique())
for city in all_cities_sorted:
    prof_pct = round(float(prof_share.get(city, 0)), 1)
    eh_pct = round(float(entire_home_share.get(city, 0)), 1)
    mean_lst = round(float(host_listing_stats.loc[city, 'mean']), 1) if city in host_listing_stats.index else 0
    median_lst = round(float(host_listing_stats.loc[city, 'median']), 1) if city in host_listing_stats.index else 0
    max_lst = int(host_listing_stats.loc[city, 'max']) if city in host_listing_stats.index else 0
    table_supply_rows.append([city, f"{prof_pct}%", f"{eh_pct}%", f"{mean_lst}", f"{median_lst}", f"{max_lst:,}"])

# Table: Review activity
table_review_rows = []
for city in avg_reviews_month.index:
    avg_rpm = round(float(avg_reviews_month[city]), 2)
    avg_total = round(float(review_stats_city.loc[city, 'avg_total_reviews']), 1)
    avg_ltm = round(float(review_stats_city.loc[city, 'avg_ltm_reviews']), 1)
    pct_rev = round(float(review_stats_city.loc[city, 'pct_with_reviews']), 1)
    recency = round(float(review_recency_12m.get(city, 0)), 1)
    table_review_rows.append([city, f"{avg_rpm}", f"{avg_total}", f"{avg_ltm}", f"{pct_rev}%", f"{recency}%"])

# Table: Availability & min nights
table_avail_rows = []
for city in all_cities_sorted:
    mean_a = round(float(avail_stats.loc[city, 'mean_avail']), 1) if city in avail_stats.index else 0
    median_a = round(float(avail_stats.loc[city, 'median_avail']), 1) if city in avail_stats.index else 0
    zero_a = round(float(zero_avail_pct.get(city, 0)), 1)
    mean_mn = round(float(min_nights_stats.loc[city, 'mean_min']), 1) if city in min_nights_stats.index else 0
    median_mn = round(float(min_nights_stats.loc[city, 'median_min']), 1) if city in min_nights_stats.index else 0
    pct30 = round(float(min_nights_stats.loc[city, 'pct_over_30']), 1) if city in min_nights_stats.index else 0
    table_avail_rows.append([city, f"{mean_a}", f"{median_a}", f"{zero_a}%", f"{mean_mn}", f"{median_mn}", f"{pct30}%"])

# Table: Price by room type
table_price_room_rows = []
for city in chart3_cities:
    row = [city]
    for rt in ['Entire home/apt', 'Private room', 'Shared room', 'Hotel room']:
        if city in price_by_room.index and rt in price_by_room.columns:
            v = price_by_room.loc[city, rt]
            cnt = len(df_price[(df_price['city']==city) & (df_price['room_type']==rt)])
            if v > 0 and cnt > 0:
                row.append(f"${v:,.0f} (n={cnt:,})")
            else:
                row.append("N/A")
        else:
            row.append("N/A")
    table_price_room_rows.append(row)

# ============================================================
# GENERATE HTML
# ============================================================

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Airbnb Market Comparison: Pricing, Supply & Guest Demand Across Major Cities</title>
