: {{ beginAtZero: true, title: {{ display: true, text: '% of Listings by Hosts with 5+ Listings' }}, max: 70 }} }}", "+    }}", "+}});", "+", "+// Chart 5: Entire home share", "+new Chart(document.getElementById('chartEntireHome'), {{", "+    type: 'bar',", "+    data: {{", "+        labels: {json.dumps(chart5_cities)},", "+        datasets: [{{", "+            label: 'Entire Home/Apt Share (%)',", "+            data: {json.dumps(chart5_data)},", "+            backgroundColor: {json.dumps([cityColors.get(c, 'rgba(100,100,100,0.8)') for c in chart5_cities])},", "+            borderColor: {json.dumps([cityBorders.get(c, 'rgba(100,100,100,1)') for c in chart5_cities])},", "+            borderWidth: 1", "+        }}]", "+    }},", "+    options: {{...baseOptions, indexAxis: 'y',", "+        scales: {{ x: {{ beginAtZero: true, title: {{ display: true, text: '% of Listings that are Entire Home/Apt' }}, max: 100 }} }}", "+    }}", "+}});", "+", "+// Chart 6: Reviews per month", "+new Chart(document.getElementById('chartReviewsPerMonth'), {{", "+    type: 'bar',", "+    data: {{", "+        labels: {json.dumps(chart6_cities)},", "+        datasets: [{{", "+            label: 'Avg Reviews per Month',", "+            data: {json.dumps(chart6_data)},", "+            backgroundColor: {json.dumps([cityColors.get(c, 'rgba(100,100,100,0.8)') for c in chart6_cities])},", "+            borderColor: {json.dumps([cityBorders.get(c, 'rgba(100,100,100,1)') for c in chart6_cities])},", "+            borderWidth: 1", "+        }}]", "+    }},", "+    options: {{...baseOptions,", "+        scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'Average Reviews per Month' }} }} }}", "+    }}", "+}});", "+", "+// Chart 7: Mean availability", "+new Chart(document.getElementById('chartAvailability'), {{", "+    type: 'bar',", "+    data: {{", "+        labels: {json.dumps(chart7_cities)},", "+        datasets: [{{", "+            label: 'Mean Availability (days/year)',", "+            data: {json.dumps(chart7_data)},", "+            backgroundColor: {json.dumps([cityColors.get(c, 'rgba(100,100,100,0.8)') for c in chart7_cities])},", "+            borderColor: {json.dumps([cityBorders.get(c, 'rgba(100,100,100,1)') for c in chart7_cities])},", "+            borderWidth: 1", "+        }}]", "+    }},", "+    options: {{...baseOptions,", "+        scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'Mean Availability (days/year)' }}, max: 365 }} }}", "+    }}", "+}});", "+", "+// Chart 8: Room type mix (stacked)", "+new Chart(document.getElementById('chartRoomTypeMix'), {{", "+    type: 'bar',", "+    data: {{", "+        labels: {json.dumps(chart8_cities)},", "+        datasets: {json.dumps(chart8_datasets)}", "+    }},", "+    options: {{...baseOptions,", "+        scales: {{", "+            x: {{ stacked: true }},", "+            y: {{ stacked: true, title: {{ display: true, text: '% of Listings' }}, max: 100 }}", "+        }}", "+    }}", "+}});", "+", "+// Chart 9: Zero availability", "+new Chart(document.getElementById('chartZeroAvail'), {{", "+    type: 'bar',", "+    data: {{", "+        labels: {json.dumps(chart9_cities)},", "+        datasets: [{{", "+            label: '% Listings with Zero Availability',", "+            data: {json.dumps(chart9_data)},", "+            backgroundColor: {json.dumps([cityColors.get(c, 'rgba(100,100,100,0.8)') for c in chart9_cities])},", "+            borderColor: {json.dumps([cityBorders.get(c, 'rgba(100,100,100,1)') for c in chart9_cities])},", "+            borderWidth: 1", "+        }}]", "+    }},", "+    options: {{...baseOptions,", "+        scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: '% of Listings with 0 Days Available' }}, max: 50 }} }}", "+    }}", "+}});", "+</script>", "+", "+</body>", "+</html>", "+"""", "+", "+# Write the report", "+with open('/app/output/final_report.html', 'w', encoding='utf-8') as f:", "+    f.write(html)", "+", "+print(f"Report written to /app/output/final_report.html")", "+print(f"File size: {len(html):,} bytes")"]}], "originalFile": "import pandas as pd
import numpy as np
import json
from datetime import datetime

# Load data
df = pd.read_csv('/app/benchmark/data.csv')
print(f"Total rows loaded: {len(df)}")
print(f"Columns: {list(df.columns)}")
print(f"\nCities: {df['city'].unique().tolist()}")
print(f"\nRoom types: {df['room_type'].unique().tolist()}")
print(f"\nPrice null count: {df['price'].isna().sum()}")
print(f"Price non-null count: {df['price'].notna().sum()}")
print(f"\nCity value counts:")
print(df['city'].value_counts())

# Clean price - exclude nulls for price analysis
df_price = df[df['price'].notna()].copy()
print(f"\nListings with price data: {len(df_price)}")

# ============================================================
# SECTION 1: Global Market Overview
# ============================================================
print("\n=== SECTION 1: Global Market Overview ===")

# Listings per city
listings_per_city = df.groupby('city').size().reset_index(name='total_listings')
listings_per_city = listings_per_city.sort_values('total_listings', ascending=False)
print(listings_per_city.to_string(index=False))

# Room type breakdown per city
room_type_by_city = df.groupby(['city', 'room_type']).size().reset_index(name='count')
room_type_pivot = room_type_by_city.pivot_table(index='city', columns='room_type', values='count', fill_value=0)
room_type_pivot['Total'] = room_type_pivot.sum(axis=1)
print("\nRoom type breakdown:")
print(room_type_pivot.to_string())

# Overall price distribution per city
price_stats = df_price.groupby('city')['price'].agg(['median', 'mean', 'std', 'min', 'max']).reset_index()
price_stats.columns = ['city', 'median_price', 'mean_price', 'std_price', 'min_price', 'max_price']
price_stats = price_stats.sort_values('median_price', ascending=False)
print("\nPrice stats by city:")
print(price_stats.to_string(index=False))

# ============================================================
# SECTION 2: Pricing Dynamics
# ============================================================
print("\n=== SECTION 2: Pricing Dynamics ===")

# Median and mean price by city and room type
price_by_city_room = df_price.groupby(['city', 'room_type'])['price'].agg(['median', 'mean', 'count']).reset_index()
price_by_city_room.columns = ['city', 'room_type', 'median_price', 'mean_price', 'count']
print(price_by_city_room.to_string(index=False))

# Price dispersion (IQR) by city
price_iqr = df_price.groupby('city')['price'].describe().reset_index()
price_iqr['IQR'] = price_iqr['75%'] - price_iqr['25%']
price_iqr['cv'] = price_iqr['std'] / price_iqr['mean']  # coefficient of variation
print("\nPrice dispersion by city:")
print(price_iqr[['city', '25%', '50%', '75%', 'IQR', 'cv']].to_string(index=False))

# ============================================================
# SECTION 3: Supply Structure & Host Concentration
# ============================================================
print("\n=== SECTION 3: Supply Structure & Host Concentration ===")

# Professional host share (calculated_host_listings_count >= 5)
df['is_professional'] = df['calculated_host_listings_count'] >= 5
prof_share = df.groupby('city')['is_professional'].mean().reset_index()
prof_share.columns = ['city', 'professional_host_share']
prof_share['professional_host_pct'] = (prof_share['professional_host_share'] * 100).round(1)
prof_share = prof_share.sort_values('professional_host_pct', ascending=False)
print("Professional host share:")
print(prof_share.to_string(index=False))

# Entire home share
df['is_entire_home'] = df['room_type'] == 'Entire home/apt'
entire_home_share = df.groupby('city')['is_entire_home'].mean().reset_index()
entire_home_share.columns = ['city', 'entire_home_share']
entire_home_share['entire_home_pct'] = (entire_home_share['entire_home_share'] * 100).round(1)
entire_home_share = entire_home_share.sort_values('entire_home_pct', ascending=False)
print("\nEntire home/apt share:")
print(entire_home_share.to_string(index=False))

# Host listing count distribution
host_dist = df.groupby('city')['calculated_host_listings_count'].agg(['mean', 'median', 'max']).reset_index()
host_dist.columns = ['city', 'mean_listings', 'median_listings', 'max_listings']
host_dist = host_dist.sort_values('mean_listings', ascending=False)
print("\nHost listing count stats:")
print(host_dist.to_string(index=False))

# ============================================================
# SECTION 4: Guest Demand & Review Activity
# ============================================================
print("\n=== SECTION 4: Guest Demand & Review Activity ===")

# Average reviews per month by city (exclude null)
df_reviews = df[df['reviews_per_month'].notna()].copy()
avg_reviews = df_reviews.groupby('city')['reviews_per_month'].mean().reset_index()
avg_reviews.columns = ['city', 'avg_reviews_per_month']
avg_reviews['avg_reviews_per_month'] = avg_reviews['avg_reviews_per_month'].round(2)
avg_reviews = avg_reviews.sort_values('avg_reviews_per_month', ascending=False)
print("Average reviews per month:")
print(avg_reviews.to_string(index=False))

# Reviews per month by room type
reviews_by_room = df_reviews.groupby(['city', 'room_type'])['reviews_per_month'].mean().reset_index()
reviews_by_room.columns = ['city', 'room_type', 'avg_reviews_per_month']
print("\nReviews per month by room type (top):")
print(reviews_by_room.sort_values('avg_reviews_per_month', ascending=False).head(20).to_string(index=False))

# Total reviews and LTM reviews
review_stats = df.groupby('city').agg(
    total_reviews=('number_of_reviews', 'sum'),
    avg_total_reviews=('number_of_reviews', 'mean'),
    avg_ltm_reviews=('number_of_reviews_ltm', 'mean'),
    pct_with_reviews=('number_of_reviews', lambda x: (x > 0).mean() * 100)
).reset_index()
review_stats = review_stats.sort_values('avg_reviews', ascending=False) if 'avg_reviews' in review_stats.columns else review_stats
print("\nReview stats by city:")
print(review_stats.to_string(index=False))

# Last review recency - how many listings reviewed in last 6 months?
df['last_review_dt'] = pd.to_datetime(df['last_review'], errors='coerce')
scrape_date = pd.Timestamp('2026-03-29')
df['months_since_last_review'] = (scrape_date - df['last_review_dt']).dt.days / 30
recent_review = df[df['months_since_last_review'] <= 6].groupby('city').size() / df.groupby('city').size() * 100
recent_review = recent_review.reset_index()
recent_review.columns = ['city', 'pct_reviewed_last_6m']
recent_review['pct_reviewed_last_6m'] = recent_review['pct_reviewed_last_6m'].round(1)
print("\n% listings with review in last 6 months:")
print(recent_review.sort_values('pct_reviewed_last_6m', ascending=False).to_string(index=False))

# ============================================================
# SECTION 5: Availability & Booking Constraints
# ============================================================
print("\n=== SECTION 5: Availability & Booking Constraints ===")

# Mean availability by city
avail_stats = df.groupby('city')['availability_365'].agg(['mean', 'median', 'std']).reset_index()
avail_stats.columns = ['city', 'mean_availability', 'median_availability', 'std_availability']
avail_stats['mean_availability'] = avail_stats['mean_availability'].round(1)
avail_stats['median_availability'] = avail_stats['median_availability'].round(1)
avail_stats = avail_stats.sort_values('mean_availability', ascending=False)
print("Availability stats:")
print(avail_stats.to_string(index=False))

# Minimum nights stats
min_nights_stats = df.groupby('city')['minimum_nights'].agg(['mean', 'median', lambda x: (x > 30).mean() * 100]).reset_index()
min_nights_stats.columns = ['city', 'mean_min_nights', 'median_min_nights', 'pct_over_30_nights']
min_nights_stats['mean_min_nights'] = min_nights_stats['mean_min_nights'].round(1)
min_nights_stats['median_min_nights'] = min_nights_stats['median_min_nights'].round(1)
min_nights_stats['pct_over_30_nights'] = min_nights_stats['pct_over_30_nights'].round(1)
min_nights_stats = min_nights_stats.sort_values('median_min_nights', ascending=False)
print("\nMinimum nights stats:")
print(min_nights_stats.to_string(index=False))

# % of listings with 0 availability
zero_avail = df.groupby('city').apply(lambda x: (x['availability_365'] == 0).mean() * 100).reset_index()
zero_avail.columns = ['city', 'pct_zero_availability']
zero_avail['pct_zero_availability'] = zero_avail['pct_zero_availability'].round(1)
zero_avail = zero_avail.sort_values('pct_zero_availability', ascending=False)
print("\n% listings with zero availability:")
