import pandas as pd
import numpy as np
import json
from datetime import datetime

# ============================================================
# LOAD AND PREPARE DATA
# ============================================================
df = pd.read_csv('/app/benchmark/data.csv')
df_price = df[df['price'].notna()].copy()
df_reviews = df[df['reviews_per_month'].notna()].copy()

# Derived columns
df['is_professional'] = df['calculated_host_listings_count'] >= 5
df['is_entire_home'] = df['room_type'] == 'Entire home/apt'
df['last_review_dt'] = pd.to_datetime(df['last_review'], errors='coerce')
scrape_date = pd.Timestamp('2026-03-29')
df['days_since_review'] = (scrape_date - df['last_review_dt']).dt.days

city_order = df['city'].value_counts().index.tolist()

# ============================================================
# COMPUTE ALL KPIs
# ============================================================

# Section 1
listings_per_city = df.groupby('city').size().reindex(city_order)
room_type_pct = df.groupby('city')['room_type'].value_counts(normalize=True).unstack(fill_value=0) * 100
room_type_count = df.groupby('city')['room_type'].value_counts().unstack(fill_value=0)

# Section 2
price_median_city = df_price.groupby('city')['price'].median().sort_values(ascending=False)
price_by_room = df_price.groupby(['city', 'room_type'])['price'].median().unstack(fill_value=0)
price_dispersion = df_price.groupby('city')['price'].agg(
    q25=lambda x: x.quantile(0.25), median='median',
    q75=lambda x: x.quantile(0.75), std='std', mean='mean'
).reset_index()
price_dispersion['iqr'] = price_dispersion['q75'] - price_dispersion['q25']
price_dispersion['cv'] = (price_dispersion['std'] / price_dispersion['mean']).round(2)

# Section 3
prof_share = (df.groupby('city')['is_professional'].mean() * 100).sort_values(ascending=False)
entire_home_share = (df.groupby('city')['is_entire_home'].mean() * 100).sort_values(ascending=False)
host_listing_stats = df.groupby('city')['calculated_host_listings_count'].agg(['mean', 'median', 'max']).round(1)

# Section 4
avg_reviews_month = df_reviews.groupby('city')['reviews_per_month'].mean().sort_values(ascending=False).round(2)
review_stats_city = df.groupby('city').agg(
    avg_total_reviews=('number_of_reviews', 'mean'),
    avg_ltm_reviews=('number_of_reviews_ltm', 'mean'),
    pct_with_reviews=('number_of_reviews', lambda x: (x > 0).mean() * 100)
).round(1)
review_recency_12m = (df[df['days_since_review'] <= 365].groupby('city').size() / df.groupby('city').size() * 100).round(1).sort_values(ascending=False)

# Section 5
avail_stats = df.groupby('city')['availability_365'].agg(['mean', 'median']).round(1)
avail_stats.columns = ['mean_avail', 'median_avail']
zero_avail_pct = (df.groupby('city').apply(lambda x: (x['availability_365'] == 0).mean() * 100, include_groups=False)).round(1)
min_nights_stats = df.groupby('city')['minimum_nights'].agg(
    mean_min='mean', median_min='median',
    pct_over_30=lambda x: (x > 30).mean() * 100
).round(1)

# Price coverage
price_coverage = {}
for city in sorted(df['city'].unique()):
    total = len(df[df['city'] == city])
    with_price = len(df_price[df_price['city'] == city])
    price_coverage[city] = {'total': total, 'with_price': with_price, 'pct': round(with_price/total*100, 1)}

# ============================================================
# PRE-COMPUTE ALL CHART DATA (Python lists/ints only)
# ============================================================
CITY_COLORS = {
    'London': 'rgba(52, 152, 219, 0.8)', 'Paris': 'rgba(155, 89, 182, 0.8)',
    'Rome': 'rgba(46, 204, 113, 0.8)', 'Bangkok': 'rgba(243, 156, 18, 0.8)',
    'Barcelona': 'rgba(231, 76, 60, 0.8)', 'Sydney': 'rgba(26, 188, 156, 0.8)',
    'Amsterdam': 'rgba(52, 73, 94, 0.8)'
}
CITY_BORDERS = {
    'London': 'rgba(52, 152, 219, 1)', 'Paris': 'rgba(155, 89, 182, 1)',
    'Rome': 'rgba(46, 204, 113, 1)', 'Bangkok': 'rgba(243, 156, 18, 1)',
    'Barcelona': 'rgba(231, 76, 60, 1)', 'Sydney': 'rgba(26, 188, 156, 1)',
    'Amsterdam': 'rgba(52, 73, 94, 1)'
}
ROOM_COLORS = {
    'Entire home/apt': ('rgba(52, 152, 219, 0.8)', 'rgba(52, 152, 219, 1)'),
    'Private room': ('rgba(46, 204, 113, 0.8)', 'rgba(46, 204, 113, 1)'),
    'Shared room': ('rgba(243, 156, 18, 0.8)', 'rgba(243, 156, 18, 1)'),
    'Hotel room': ('rgba(155, 89, 182, 0.8)', 'rgba(155, 89, 182, 1)')
}

def city_bg(labels): return [CITY_COLORS.get(c, 'rgba(100,100,100,0.8)') for c in labels]
def city_bd(labels): return [CITY_BORDERS.get(c, 'rgba(100,100,100,1)') for c in labels]

# Chart 1: Listings per city
c1_labels = list(city_order)
c1_data = [int(listings_per_city[c]) for c in c1_labels]
c1_bg = city_bg(c1_labels)
c1_bd = city_bd(c1_labels)

# Chart 2: Median price by city
c2_labels = price_median_city.index.tolist()
c2_data = [round(float(price_median_city[c]), 0) for c in c2_labels]
c2_bg = city_bg(c2_labels)
c2_bd = city_bd(c2_labels)

# Chart 3: Price by room type (grouped)
c3_cities = ['Amsterdam', 'Bangkok', 'Barcelona', 'London', 'Rome']
c3_datasets = []
for rt in ['Entire home/apt', 'Private room', 'Shared room', 'Hotel room']:
    if rt in price_by_room.columns:
        vals = [round(float(price_by_room.loc[c, rt]), 0) if c in price_by_room.index and rt in price_by_room.columns and price_by_room.loc[c, rt] > 0 else 0 for c in c3_cities]
        c3_datasets.append({
            'label': rt, 'data': vals,
            'backgroundColor': ROOM_COLORS[rt][0], 'borderColor': ROOM_COLORS[rt][1], 'borderWidth': 1
        })

# Chart 4: Professional host share
c4_labels = prof_share.index.tolist()
c4_data = [round(float(prof_share[c]), 1) for c in c4_labels]
c4_bg = city_bg(c4_labels)
c4_bd = city_bd(c4_labels)

# Chart 5: Entire home share
c5_labels = entire_home_share.index.tolist()
c5_data = [round(float(entire_home_share[c]), 1) for c in c5_labels]
c5_bg = city_bg(c5_labels)
c5_bd = city_bd(c5_labels)

# Chart 6: Avg reviews per month
c6_labels = avg_reviews_month.index.tolist()
c6_data = [round(float(avg_reviews_month[c]), 2) for c in c6_labels]
c6_bg = city_bg(c6_labels)
c6_bd = city_bd(c6_labels)

# Chart 7: Mean availability
c7_labels = avail_stats.sort_values('mean_avail', ascending=False).index.tolist()
c7_data = [round(float(avail_stats.loc[c, 'mean_avail']), 1) for c in c7_labels]
c7_bg = city_bg(c7_labels)
c7_bd = city_bd(c7_labels)

# Chart 8: Room type mix (stacked)
c8_labels = list(city_order)
