    background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
    color: white; padding: 20px; border-radius: 10px; text-align: center;
}
.kpi-card .kpi-value { font-size: 1.8em; font-weight: 700; line-height: 1.2; }
.kpi-card .kpi-label { font-size: 0.82em; opacity: 0.85; margin-top: 4px; }
.kpi-card.alt { background: linear-gradient(135deg, #276749 0%, #2f855a 100%); }
.kpi-card.accent { background: linear-gradient(135deg, #744210 0%, #b7791f 100%); }
.table-wrap { overflow-x: auto; margin: 20px 0; }
table { width: 100%; border-collapse: collapse; font-size: 0.9em; }
thead th {
    background: var(--primary); color: white; padding: 12px 14px;
    text-align: left; font-weight: 600; font-size: 0.88em; white-space: nowrap;
}
tbody td { padding: 10px 14px; border-bottom: 1px solid var(--border); }
tbody tr:hover { background: #edf2f7; }
tbody tr:nth-child(even) { background: #f7fafc; }
tbody tr:nth-child(even):hover { background: #edf2f7; }
.chart-container {
    margin: 24px 0; padding: 16px; background: #f7fafc;
    border-radius: 8px; border: 1px solid var(--border);
}
.chart-container canvas { max-height: 420px; }
.highlight-box {
    background: var(--accent-light); border-left: 4px solid var(--accent);
    padding: 14px 18px; border-radius: 0 8px 8px 0; margin: 16px 0; font-size: 0.93em;
}
.highlight-box strong { color: var(--primary); }
.takeaway {
    background: var(--card-bg); border: 1px solid var(--border);
    border-left: 4px solid var(--accent); border-radius: 0 8px 8px 0;
    padding: 16px 20px; margin-bottom: 14px;
}
.takeaway .tk-num {
    display: inline-block; background: var(--accent); color: white;
    font-weight: 700; font-size: 0.85em; padding: 2px 10px;
    border-radius: 12px; margin-right: 8px;
}
.takeaway .tk-title { font-weight: 700; color: var(--primary); }
.takeaway .tk-body { color: var(--text-secondary); margin-top: 6px; font-size: 0.94em; }
.report-footer {
    text-align: center; color: var(--text-secondary); font-size: 0.85em;
    padding: 24px 0 12px; border-top: 1px solid var(--border); margin-top: 12px;
}
.toc {
    background: var(--card-bg); border-radius: 10px; padding: 24px 32px;
    margin-bottom: 28px; box-shadow: 0 1px 4px rgba(0,0,0,0.06);
}
.toc h2 { color: var(--primary); font-size: 1.2em; margin-bottom: 12px; }
.toc ol { padding-left: 20px; }
.toc li { margin-bottom: 6px; font-size: 0.95em; }
.toc a { color: var(--accent); text-decoration: none; }
.toc a:hover { text-decoration: underline; }
h3.section-sub { color: var(--primary); margin: 24px 0 12px; font-size: 1.15em; }
@media print {
    body { background: white; }
    .section { box-shadow: none; border: 1px solid var(--border); }
    .report-header { box-shadow: none; }
}
</style>
</head>
