)},", "-        datasets: [{{", "+    data: {", "+        labels: """ + json.dumps(c7_labels) + """,", "+        datasets: [{", "             label: 'Mean Availability (days/year)',", "-            data: {json.dumps(chart7_data)},", "-            backgroundColor: {json.dumps([cityColors.get(c, 'rgba(100,100,100,0.8)') for c in chart7_cities])},", "-            borderColor: {json.dumps([cityBorders.get(c, 'rgba(100,100,100,1)') for c in chart7_cities])},", "+            data: """ + json.dumps(c7_data) + """,", "+            backgroundColor: """ + json.dumps(c7_bg) + """,", "+            borderColor: """ + json.dumps(c7_bd) + """,", "             borderWidth: 1", "-        }}]", "-    }},", "-    options: {{...baseOptions,", "-        scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'Mean Availability (days/year)' }}, max: 365 }} }}", "-    }}", "-}});", "+        }]", "+    },", "+    options: {", "+        responsive: true, maintainAspectRatio: true,", "+        plugins: { legend: { position: 'top' }, tooltip: { mode: 'index', intersect: false } },", "+        scales: { y: { beginAtZero: true, title: { display: true, text: 'Mean Availability (days/year)' }, max: 365 } }", "+    }", "+});", " ", " // Chart 8: Room type mix (stacked)", "-new Chart(document.getElementById('chartRoomTypeMix'), {{", "+new Chart(document.getElementById('chartRoomTypeMix'), {", "     type: 'bar',", "-    data: {{", "-        labels: {json.dumps(chart8_cities)},", "-        datasets: {json.dumps(chart8_datasets)}", "-    }},", "-    options: {{...baseOptions,", "-        scales: {{", "-            x: {{ stacked: true }},", "-            y: {{ stacked: true, title: {{ display: true, text: '% of Listings' }}, max: 100 }}", "-        }}", "-    }}", "-}});", "+    data: {", "+        labels: """ + json.dumps(c8_labels) + """,", "+        datasets: """ + json.dumps(c8_datasets) + """", "+    },", "+    options: {", "+        responsive: true, maintainAspectRatio: true,", "+   